import React, { useState } from "react";
import { motion } from "framer-motion";
import {
  FaWallet,
  FaMoneyBillWave,
  FaTags,
  FaCalendarAlt,
  FaStickyNote,
} from "react-icons/fa";

import { addExpense } from "../../api/expenseApi";

const ExpenseTracker = ({ refreshExpenses }) => {
  const [expenseName, setExpenseName] = useState("");
  const [amount, setAmount] = useState("");
  const [category, setCategory] = useState("Food");
  const [date, setDate] = useState("");
  const [description, setDescription] = useState("");
  const [loading, setLoading] = useState(false);

  const handleSubmit = async (e) => {
    e.preventDefault();

    if (
      !expenseName.trim() ||
      !amount ||
      !category ||
      !date
    ) {
      alert("Please fill all required fields.");
      return;
    }

    try {
      setLoading(true);

      const response = await addExpense({
        name: expenseName,
        amount: Number(amount),
        category,
        date,
        description,
      });

      if (response.data.success) {
        alert("✅ Expense Added Successfully!");

        setExpenseName("");
        setAmount("");
        setCategory("Food");
        setDate("");
        setDescription("");

        if (refreshExpenses) {
          refreshExpenses();
        }
      } else {
        alert("Failed to add expense.");
      }
    } catch (error) {
      console.error(error);

      alert(
        error.response?.data?.message ||
          "Something went wrong while adding expense."
      );
    } finally {
      setLoading(false);
    }
  };

  return 
  <motion.div
  initial={{ opacity: 0, y: 60 }}
  animate={{ opacity: 1, y: 0 }}
  transition={{ duration: 0.6 }}
  whileHover={{
    scale: 1.01,
    boxShadow: "0 20px 40px rgba(0,0,0,0.12)",
  }}
  className="max-w-4xl mx-auto bg-white rounded-3xl shadow-xl p-8 relative overflow-hidden"
>
  {/* Animated Background */}
  <motion.div
    animate={{
      x: [0, 120, 0],
      y: [0, 60, 0],
    }}
    transition={{
      duration: 15,
      repeat: Infinity,
    }}
    className="absolute w-72 h-72 bg-red-300 rounded-full blur-3xl opacity-20 -top-24 -left-24"
  />

  <motion.div
    animate={{
      x: [0, -80, 0],
      y: [0, 100, 0],
    }}
    transition={{
      duration: 18,
      repeat: Infinity,
    }}
    className="absolute w-80 h-80 bg-orange-300 rounded-full blur-3xl opacity-20 -bottom-24 -right-24"
  />
  {/* Submit Button */}
<motion.button
  type="submit"
  disabled={loading}
  whileHover={{
    scale: 1.03,
    boxShadow: "0px 15px 35px rgba(239,68,68,0.4)",
  }}
  whileTap={{ scale: 0.95 }}
  className="w-full py-4 rounded-xl bg-gradient-to-r from-red-500 to-orange-500 text-white text-lg font-bold shadow-lg"
>
  {loading ? (
    <motion.span
      animate={{ opacity: [1, 0.5, 1] }}
      transition={{ duration: 1, repeat: Infinity }}
    >
      ⏳ Adding Expense...
    </motion.span>
  ) : (
    "💸 Add Expense"
  )}
</motion.button>


</motion.div>

};

export default ExpenseTracker;